    const int TILE_SIZE = 16;
    const int UNROLL_FACTOR = 4;

    // Shared memory for tiles (use padding to avoid bank conflicts)
    __shared__ float sA[TILE_SIZE][TILE_SIZE + 1];  // +1 padding to avoid bank conflicts
    __shared__ float sB[TILE_SIZE][TILE_SIZE + 1];  // +1 padding to avoid bank conflicts

    int tx = threadIdx.x;
    int ty = threadIdx.y;

    int row = blockIdx.y * TILE_SIZE + ty;
    int col = blockIdx.x * TILE_SIZE + tx;

    float sum = 0.0f;

    // Loop over tiles
    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; t++) {
        // Load tiles into shared memory
        int t_col = t * TILE_SIZE + tx;
        int t_row = t * TILE_SIZE + ty;

        if (row < N && t_col < N) {
            sA[ty][tx] = A[row * N + t_col];
        } else {
            sA[ty][tx] = 0.0f;
        }

        if (t_row < N && col < N) {
            sB[ty][tx] = B[t_row * N + col];
        } else {
            sB[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute partial dot product with loop unrolling
        #pragma unroll
        for (int k = 0; k < TILE_SIZE; k++) {
            sum += sA[ty][k] * sB[k][tx];
        }

        __syncthreads();
    }

    // Write result to global memory
    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
